    raw_response: JSON.stringify(response).slice(0, 2000),
    extracted_text: (text || '').toString().slice(0, 1000),
    extraction_success: false,
    apiKey: ctx.apiKey,
    empresaId: ctx.empresaId
  };
}

// El webhook entrega el payload en $json.body (n8n lo anida bajo 'body'
// cuando el Content-Type es application/json). Aceptamos ambos por robustez.
const raw = $json || {};
const d = raw.body || raw;
const provider = (d.email_provider || 'outlook').toLowerCase();

// $env.* está bloqueado por N8N_BLOCK_ENV_ACCESS_IN_NODE. El fallback
// del callback va hardcoded. El backend puede sobreescribir enviando 'callbackUrl'.
return {
  requestId: d.requestId || '',
  apiKey: d.apiKey || '',
  empresaId: d.empresaId || null,
  startDate: d.startDate || '',
  endDate: d.endDate || '',
  email: d.email || '',
  email_provider: provider,
  credential_email_id: d.credential_email_id || '',
  callbackUrl: d.callbackUrl || 'http://127.0.0.1:8000/api/asistente/callback/search-results'
};

// Graph responde { value: [ ...messages ] } en un solo item. Lo expandimos
// en items individuales para que 'Normalizar Adjuntos' procese cada correo
// con la misma lógica que las otras ramas.
const raw = $json || {};
const messages = raw.value || raw || [];
if (!Array.isArray(messages)) {
  return [{ empty: true, error: 'Respuesta Graph inesperada', raw: JSON.stringify(raw).slice(0, 500) }];
}
if (messages.length === 0) {
  return [{ empty: true }];
}
return messages;

// Normaliza la salida de cualquiera de los providers a un esquema único.
// Cada item de entrada es un correo; emitimos un item por cada adjunto PDF/ZIP.
// Incluye el contenido base64 del adjunto para que el backend pueda procesarlo
// sin necesidad de descargarlo por separado.
const ctx = $('Extraer Contexto').first().json;
const results = [];

for (const item of $input.all()) {
  const email = item.json || {};
  let subject, from, date, attachments, messageId, provider;

  // Outlook Graph (detectar por conversationId, único de MS Graph)
  if (email.conversationId) {
    provider = 'outlook';
    subject = email.subject || 'Sin asunto';
    from = email.from?.emailAddress?.address
        || email.from?.address
        || (typeof email.from === 'string' ? email.from : '')
        || '';
    date = email.receivedDateTime || '';
    attachments = email.attachments || [];
    messageId = email.id;
  }
  // Gmail
  else if (email.payload?.headers) {
    provider = 'gmail';
    const headers = email.payload.headers || [];
    subject = headers.find(h => h.name === 'Subject')?.value || 'Sin asunto';
    from = headers.find(h => h.name === 'From')?.value || '';
    date = headers.find(h => h.name === 'Date')?.value || '';
    const walk = (parts) => {
      const out = [];
      for (const p of (parts || [])) {
        if (p.filename && p.body?.attachmentId) {
          out.push({ name: p.filename, mimeType: p.mimeType, attachmentId: p.body.attachmentId, size: p.body.size });
        }
        if (p.parts) out.push(...walk(p.parts));
      }
      return out;
    };
    attachments = walk(email.payload.parts);
    messageId = email.id;
  }
  else {
    // Formato desconocido → salta
    continue;
  }

  for (const att of attachments) {
    const name = att.name || att.filename || 'archivo';
    const ext = (name.split('.').pop() || '').toLowerCase();
    if (ext !== 'pdf' && ext !== 'zip') continue;

    // Outlook con $expand=attachments trae contentBytes ya en base64.
    // Gmail requiere descarga aparte con attachmentId — la haría el backend.
    const contentB64 = att.contentBytes
      || att.content
      || att.data
      || '';

    results.push({
      filename: name,
      size: att.size || (contentB64 ? Math.floor(contentB64.length * 3 / 4) : 0),
      date,
      sender: from,
      subject,
      contentType: att.contentType || att.mimeType || '',
      storage_path: name,
      messageId,
      attachmentId: att.id || att.attachmentId || '',
      sourceId: messageId + '::' + name,
      provider,
      content_base64: contentB64,
      ...ctx
    });
  }
}

if (results.length === 0) {
  return [{ empty: true, ...ctx }];
}
return results;
